module ActionController;module EtagWithTemplateDigest;extend ActiveSupport::Concern;include ActionController::ConditionalGet;included do class_attribute:etag_with_template_digest,default:true;etag do |options|determine_template_etag(options) if etag_with_template_digest;end;end;private;def determine_template_etag(options)if template=pick_template_for_etag(options);lookup_and_digest_template(template);end;end;def pick_template_for_etag(options)unless options[:template]==false;options[:template]||lookup_context.find_all(action_name,_prefixes).first&.virtual_path;end;end;def lookup_and_digest_template(template)ActionView::Digestor.digest name:template,format:nil,finder:lookup_context;end;end;end
